function xEscape(value) {
  return String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
}
function xBadge(text, tone = "green") { return `<span class="x-badge ${tone}">${xEscape(text)}</span>`; }
function xButton(text, action, secondary = false) { return `<button class="btn ${secondary ? "secondary" : "accent"}" data-x="${action}">${text}</button>`; }
function xHeading(kicker, title, description, action = "") { return `<div class="x-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`; }
function xStats(items) { return `<section class="x-stats">${items.map(([value, label, note]) => `<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join("")}</section>`; }
function xSource(source) {
  return `<details class="x-source"><summary><span class="x-channel ${source.color}">${source.mark}</span><span class="x-source-text"><small>${xEscape(source.channel)} <span>· ${xEscape(source.time)}</span></small><strong>${xEscape(source.title)}</strong></span>${xBadge(source.scope, source.scope === "PRIVATE" ? "blue" : "green")}</summary><div class="x-source-detail"><p>${xEscape(source.detail)}</p><small>Fictional demo source · ${source.scope === "PRIVATE" ? "Visible only in your personal workspace. Excluded from all team and leadership views." : "Approved extract only. Original permissions remain attached to the evidence."}</small></div></details>`;
}
function startExperience(path) {
  if (path === "/") { state.route = "demo-hub"; render(); return true; }
  if (path === "/demos") { state.route = "demo-hub"; render(); return true; }
  if (path === "/individual" || path === "/sme" || path === "/third-party") {
    state.route = path.slice(1); render(); return true;
  }
  if (path === "/organisation") { state.route = "login"; render(); return true; }
  if (path === "/organisation/live") { state.user = seed.users[0]; state.role = "manager"; state.route = "live-overview"; render(); return true; }
  if (path === "/third-party/due-diligence") {
    state.user = seed.users.find(user => user.role === "consultant"); state.role = "consultant"; state.route = "consulting-diligence"; render(); return true;
  }
  return false;
}
function renderExperience() {
  if (state.route === "demo-hub") { renderDemoHub(); return true; }
  if (state.route === "individual") { renderIndividual(); return true; }
  if (state.route === "sme") { renderSME(); return true; }
  if (state.route === "third-party") { renderThirdParty(); return true; }
  return false;
}
function mountExperienceNavigation() {
  if (!["demo-hub", "individual", "sme", "third-party"].includes(state.route) && state.role !== "consultant") return;
  const bar = document.createElement("nav");
  bar.className = "x-demo-nav";
  bar.setAttribute("aria-label", "Demo experiences");
  const current = state.route === "individual" ? "individual" : state.route === "sme" ? "sme" : state.route === "third-party" || state.role === "consultant" ? "third-party" : state.route === "demo-hub" ? "" : "organisation";
  bar.innerHTML = `<a href="/demos" class="x-all-demos">&larr; All demos</a><div>${[["individual", "Individual"], ["sme", "SME"], ["organisation", "Large organisation"], ["third-party", "Third-party"]].map(([path, label]) => `<a href="/${path}" ${current === path ? 'aria-current="page"' : ""}>${label}</a>`).join("")}</div><span>Fictional data · Simulated connections</span>`;
  document.getElementById("app").prepend(bar);
}
