// AI boundary: deterministic demo adapters can be replaced without changing view state.
const fieldedDemoAI = {
  reply(kind, question) {
    const normalized = question.toLowerCase();
    if (kind === "personal") {
      if (/skill|career|grow|learn/.test(normalized)) return "Your Atlas call shows stakeholder alignment. A useful next step is commercial storytelling: put the cost, value and decision on the proposal's first page. Add that to your private growth plan; it is not shared with your employer.";
      if (/process|efficient|time|repeat/.test(normalized)) return "The weekly report and steering deck repeat the same status. Try one decision log with owners and dates, then link to it. Test it for two weeks before judging whether it saves time. Your presentation is the source; this is a suggestion, not a measured result.";
      if (/proposal|atlas|priorit|today|work/.test(normalized)) return "Start with Atlas. The client email asks for implementation and support to be separated; the call asks for a phased plan. Draft the cost table, identify the two unowned assumptions in proposal v3, then request confirmation before you send. These sources stay private.";
      return "I can ground this demo in your Atlas proposal, approval process and skills plan. Which of those would you like to explore? I do not have evidence for other work, so I won't invent a recommendation.";
    }
    if (/handover|process|improv/.test(normalized)) return "Trial a five-minute kickoff agreement: scope, acceptance criteria, decision owner and escalation route. The Atlas call and delivery thread suggest the handover is unclear. Review returned handovers after two weeks; the evidence does not establish individual blame.";
    if (/scope|atlas|focus|block|today|priorit/.test(normalized)) {
      const task = experienceState.teamTasks[0];
      return `The Atlas scope task is currently ${task.status.toLowerCase()} and owned by ${task.owner}. Confirm whether analytics belongs in phase one before design sign-off. The call and statement of work disagree, so a client decision is needed, not an assumption.`;
    }
    return "Thanks. Treat that as a perspective to validate with the team, not a confirmed finding. In this demo I can help with Atlas scope, the delivery handover and review comments. Which process should we examine?";
  },
  extractRequirements(policy) {
    return policy.split(/\n+/).map(line => line.trim()).filter(Boolean).map((clause, index) => ({
      id: `req-${index + 1}`, clause, title: clause.replace(/^\d+[.)]\s*/, ""),
      owner: /personal|retention|deletion|privacy/i.test(clause) ? "Aisha Patel · Data protection" : /access|incident|MFA/i.test(clause) ? "Tom Reed · IT security" : "James Holloway · Executive sponsor",
      question: `Please describe how Redwood meets this requirement and identify the supporting document, owner and date: ${clause}`,
      answer: "", evidence: "", approved: false, disclosed: false
    }));
  }
};
