function bindExperienceEvents() {
  document.querySelectorAll("[data-x-tab]").forEach(button => button.addEventListener("click", () => { experienceState[state.route === "individual" ? "personalTab" : "teamTab"] = button.dataset.xTab; render(); }));
  document.querySelectorAll("[data-personal-task]").forEach(input => input.addEventListener("change", () => { experienceState.tasks.find(task => task.id === input.dataset.personalTask).done = input.checked; render(); }));
  document.querySelectorAll("[data-personal-idea]").forEach(button => button.addEventListener("click", () => { experienceState.applied.push(button.dataset.personalIdea); experienceState.tasks.push({ id: button.dataset.personalIdea, title: button.dataset.taskTitle, project: "Personal process experiment", time: "Next week", done: false }); render(); }));
  document.querySelectorAll("[data-skill]").forEach(button => button.addEventListener("click", () => { experienceState.skills.push(Number(button.dataset.skill)); render(); }));
  document.querySelectorAll("[data-team-task]").forEach(button => button.addEventListener("click", () => { experienceState.activeTeamTask = button.dataset.teamTask; render(); }));
  document.querySelectorAll("[data-team-owner], [data-team-status]").forEach(select => select.addEventListener("change", () => { const owner = "teamOwner" in select.dataset; const task = experienceState.teamTasks.find(item => item.id === select.dataset[owner ? "teamOwner" : "teamStatus"]); task[owner ? "owner" : "status"] = select.value; render(); }));
  document.querySelectorAll("[data-feed-filter]").forEach(button => button.addEventListener("click", () => { experienceState.sourceFilter = button.dataset.feedFilter; render(); }));
  document.querySelectorAll("[data-coach]").forEach(form => form.addEventListener("submit", event => { event.preventDefault(); const question = new FormData(form).get("question").trim(); const pending = engineThread(`coach-${form.dataset.coach}`).files; if (!question && !pending.length) return; const files = engineTakeAttachments(`coach-${form.dataset.coach}`); const messages = form.dataset.coach === "personal" ? experienceState.coach : experienceState.teamCoach; messages.push({ role: "user", content: question, files }, { role: "assistant", content: files.length ? "Your attachments are in this conversation, kept locally. What should we focus on in them?" : fieldedDemoAI.reply(form.dataset.coach, question) }); render(); const log = document.querySelector(".x-coach-log"); if (log) log.scrollTop = log.scrollHeight; }));
  document.querySelectorAll("[data-x]").forEach(button => button.addEventListener("click", () => handleExperienceAction(button.dataset.x)));
  const d = experienceState.diligence;
  document.querySelectorAll("[data-dd-stage]").forEach(button => button.addEventListener("click", () => { savePolicyDraft(); d.stage = button.dataset.ddStage; render(); }));
  document.querySelectorAll("[data-dd-title]").forEach(input => input.addEventListener("change", () => { const req = d.requirements[Number(input.dataset.ddTitle)]; const value = input.value.trim(); if (!value) { input.value = req.title; return; } engineResetThread(`dd-${req.id}`); req.title = value; req.question = `Please provide evidence for: ${value}`; req.answer = ""; req.evidence = ""; req.approved = false; req.disclosed = false; }));
  document.querySelectorAll("[data-dd-owner]").forEach(input => input.addEventListener("change", () => { const req = d.requirements[Number(input.dataset.ddOwner)]; engineResetThread(`dd-${req.id}`); req.owner = input.value; req.answer = ""; req.evidence = ""; req.approved = false; req.disclosed = false; render(); }));
  document.querySelectorAll("[data-dd-select]").forEach(button => button.addEventListener("click", () => { d.selected = Number(button.dataset.ddSelect); d.stage = "interviews"; render(); }));
  document.querySelectorAll("[data-dd-approve]").forEach(button => button.addEventListener("click", () => { d.requirements[Number(button.dataset.ddApprove)].approved = true; render(); }));
  document.querySelectorAll("[data-dd-disclose]").forEach(input => input.addEventListener("change", () => { d.requirements[Number(input.dataset.ddDisclose)].disclosed = input.checked; render(); }));
  document.getElementById("dd-file")?.addEventListener("change", async event => {
    const file = event.target.files[0]; if (!file) return;
    if (file.size > 30000 || !/\.(txt|md)$/i.test(file.name)) { d.error = "Choose a Text or Markdown file up to 30 KB."; render(); return; }
    try { d.policy = await file.text(); d.filename = file.name; d.error = ""; render(); } catch { d.error = "The file could not be read. Paste the text instead."; render(); }
  });
  document.getElementById("dd-response")?.addEventListener("submit", event => {
    event.preventDefault(); const data = new FormData(event.currentTarget); const req = d.requirements[d.selected];
    if (!String(data.get("answer")).trim() || !String(data.get("evidence")).trim()) return;
    req.answer = String(data.get("answer")).trim(); req.evidence = String(data.get("evidence")).trim(); req.attachments = [...(req.attachments || []), ...engineDiligenceAttachmentReferences(`dd-${req.id}`)]; if (req.attachments.length) req.evidence += " | Attached locally: " + req.attachments.map(file => file.name).join(", "); req.approved = false; req.disclosed = false; render();
  });
}
function savePolicyDraft() { const field = document.getElementById("dd-policy"); if (field) experienceState.diligence.policy = field.value; }
function handleExperienceAction(action) {
  const e = experienceState; const d = e.diligence;
  if (action === "apply-proposal" && !e.applied.includes("proposal")) { e.applied.push("proposal"); e.tasks[0].title = "Finish Atlas proposal: cost table + assumption check"; }
  if (action === "personal-processes") e.personalTab = "processes";
  if (action === "share-observation") {
    if (!document.getElementById("share-consent").checked) { document.getElementById("share-status").textContent = "Please approve the exact observation before contributing."; return; }
    e.shared = true;
  }
  if (action === "invite") e.invitation = `${location.origin}/sme?invite=priya-demo`;
  if (action === "adopt-team") e.teamImprovement = true;
  if (action === "live-advance") e.liveStep = e.liveStep >= 1 ? 0 : e.liveStep + 1;
  if (action === "live-support") e.liveAction = true;
  if (action === "dd-extract") {
    savePolicyDraft();
    if (!d.policy.trim()) { d.error = "Add at least one policy requirement to continue."; render(); return; }
    if (d.requirements.some(req => req.answer) && !window.confirm("Replace the collection plan? Existing demo responses and approvals will be cleared.")) return;
    d.requirements.forEach(req => engineResetThread(`dd-${req.id}`)); d.requirements = fieldedDemoAI.extractRequirements(d.policy); d.selected = 0; d.dispatched = false; d.error = ""; d.stage = "requirements";
  }
  if (action === "dd-deploy") { d.dispatched = true; d.stage = "interviews"; }
  if (action === "dd-plan") d.stage = "requirements";
  if (action === "dd-room") d.stage = "room";
  if (action === "dd-example") {
    const req = d.requirements[d.selected];
    const examples = [
      ["Redwood's information security policy is owned by James Holloway and was approved on 20 August 2026. A review is scheduled annually. This is a fictional statement; the signed policy should be requested for verification.", "SEC-001 · v2.1 · 20 August 2026 (fictional)"],
      ["MFA is enabled for staff accounts. The July access review identified two leaver accounts awaiting closure. Remediation evidence is still required; do not treat the control as fully effective.", "IAM-Review-2026-07 · Exception register (fictional)"],
      ["The inventory covers employee and customer data. Retention periods are recorded, but the deletion procedure has not yet been tested against archived exports. That remains an open evidence gap.", "DPA-Inventory-v3 · Retention schedule (fictional)"],
      ["The incident response procedure names an on-call lead. A tabletop exercise ran in June; the action log lists one unresolved notification escalation issue.", "IR-Playbook-v2 · June exercise log (fictional)"]
    ];
    const clause = req.clause.toLowerCase();
    const index = /incident/.test(clause) ? 3 : /retention|personal data/.test(clause) ? 2 : /access|mfa/.test(clause) ? 1 : /security policy/.test(clause) ? 0 : -1;
    const example = index >= 0 ? examples[index] : ["The evidence owner has acknowledged this requirement. Supporting documentation and an approval date are still outstanding. This response is a fictional collection example, not proof of compliance.", "Evidence request pending · fictional example"];
    document.querySelector('[name="answer"]').value = example[0]; document.querySelector('[name="evidence"]').value = example[1]; return;
  }
  if (action === "dd-export") {
    const included = d.requirements.filter(req => req.approved && req.disclosed);
    if (!included.length) { document.getElementById("export-status").textContent = "Approve at least one reviewed response for disclosure before exporting."; return; }
    const report = { title: "Redwood supplier assurance · Fictional demo", recipient: "Northstar Procurement", generated_at: new Date().toISOString(), limitations: "Company statements and document references only. No independent verification or compliance conclusion. Private and undisclosed evidence excluded.", evidence: included.map(({ id, title, clause, owner, answer, evidence }) => ({ id, requirement: title, source_clause: clause, owner, statement: answer, document_reference: evidence, status: "Reviewed and approved for disclosure; not independently verified" })), outstanding_requirement_count: d.requirements.length - included.length };
    const url = URL.createObjectURL(new Blob([JSON.stringify(report, null, 2)], { type: "application/json" })); const link = document.createElement("a"); link.href = url; link.download = "fielded-redwood-disclosed-evidence.json"; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); document.getElementById("export-status").textContent = `Exported ${included.length} approved responses. Undisclosed content was excluded.`; return;
  }
  render();
}
